import { Controller, Get, Patch, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 마감 상태 값은 schema.sql의 CHECK 값과 같다.
const STATUS_CLOSED = '마감';

function optionalNumber(value: unknown, integer: boolean): number | null {
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value === 'string' && value.trim() === '') {
    throw new ApiError(422, 'DAILY_PAYROLL_INVALID_INPUT', '필수 항목 누락 또는 형식 오류입니다.');
  }
  const n = Number(value);
  if (typeof value === 'boolean' || !Number.isFinite(n) || n < 0) {
    throw new ApiError(422, 'DAILY_PAYROLL_INVALID_INPUT', '숫자 형식이 올바르지 않거나 0보다 작습니다.');
  }
  if (integer && !Number.isInteger(n)) {
    throw new ApiError(422, 'DAILY_PAYROLL_INVALID_INPUT', '근무일수는 정수여야 합니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr02305Controller {
  @Get('/daily-payrolls/:dailyPayrollId')
  async getDailyPayroll(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const id = req.params['dailyPayrollId'];
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT p.daily_payroll_id AS "dailyPayrollId",
                w.worker_name AS "workerName",
                w.resident_no_enc AS "residentNoEnc",
                p.pay_date AS "payDate",
                p.work_days AS "workDays",
                p.pay_amount AS "payAmount",
                p.withholding_tax AS "withholdingTax",
                p.closing_status AS "closingStatus"
           FROM daily_payroll p
           JOIN daily_worker w ON w.daily_worker_id = p.daily_worker_id
          WHERE p.daily_payroll_id = CAST(:id AS bigint)`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'DAILY_PAYROLL_NOT_FOUND', '지급 내역이 없습니다.');
      }
      return rows[0];
    });
  }

  @Patch('/daily-payrolls/:dailyPayrollId')
  async updateDailyPayroll2(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const id = req.params['dailyPayrollId'];
    const data = checks.inputOf(req.body);
    const workDays = optionalNumber(data['workDays'], true);
    const payAmount = optionalNumber(data['payAmount'], false);
    const withholdingTax = optionalNumber(data['withholdingTax'], false);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT closing_status AS "closingStatus"
           FROM daily_payroll
          WHERE daily_payroll_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'DAILY_PAYROLL_NOT_FOUND', '지급 내역이 없습니다.');
      }
      if (found[0].closingStatus === STATUS_CLOSED) {
        throw new ApiError(409, 'DAILY_PAYROLL_ALREADY_CLOSED', '확정된 명세서는 수정할 수 없습니다. 확정 취소 절차가 필요합니다.');
      }
      const rows = await db.query(
        `UPDATE daily_payroll
            SET work_days = COALESCE(CAST(:workDays AS integer), work_days),
                pay_amount = COALESCE(CAST(:payAmount AS numeric), pay_amount),
                withholding_tax = COALESCE(CAST(:withholdingTax AS numeric), withholding_tax),
                updated_at = now()
          WHERE daily_payroll_id = CAST(:id AS bigint)
      RETURNING daily_payroll_id AS "dailyPayrollId"`,
        { id, workDays, payAmount, withholdingTax },
      );
      return rows[0];
    });
  }

  @Post('/daily-payrolls/:dailyPayrollId/close')
  @HttpCode(200)
  async closeDailyPayroll(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const id = req.params['dailyPayrollId'];
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT closing_status AS "closingStatus"
           FROM daily_payroll
          WHERE daily_payroll_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'DAILY_PAYROLL_NOT_FOUND', '지급 내역이 없습니다.');
      }
      if (found[0].closingStatus === STATUS_CLOSED) {
        throw new ApiError(409, 'DAILY_PAYROLL_ALREADY_CLOSED', '이미 확정된 명세서입니다.');
      }
      const rows = await db.query(
        `UPDATE daily_payroll
            SET closing_status = :status,
                closed_at = now(),
                updated_at = now()
          WHERE daily_payroll_id = CAST(:id AS bigint)
      RETURNING daily_payroll_id AS "dailyPayrollId",
                closing_status AS "closingStatus",
                closed_at AS "closedAt"`,
        { id, status: STATUS_CLOSED },
      );
      return rows[0];
    });
  }
}

