import { useState } from 'react';
import { call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles, Form, Field, NumberInput, DateInput, LookupSelect, RefName, ErrorText } from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Mode =
  | { kind: 'create' }
  | { kind: 'detail'; id: number }
  | { kind: 'edit'; id: number }
  | { kind: 'close'; id: number };

function CreateForm({ role, notify, onDone }: { role: string; notify: (t: string) => void; onDone: () => void }) {
  const [workerId, setWorkerId] = useState<number | string>('');
  const [payDate, setPayDate] = useState('');
  const [workDays, setWorkDays] = useState<number | string>('');
  const [payAmount, setPayAmount] = useState<number | string>('');
  const [tax, setTax] = useState<number | string>('');
  return (
    <Form
      submit="등록"
      onSubmit={async () => {
        if (workerId === '' || !payDate || workDays === '' || payAmount === '') {
          throw new Error('일용직 사원, 급여 지급일, 근무일수, 지급 금액은 필수입니다.');
        }
        await call('POST', '/daily-payrolls', role, {
          dailyWorkerId: workerId,
          payDate,
          workDays,
          payAmount,
          withholdingTax: tax,
        });
        notify('지급 내역을 등록했습니다.');
        onDone();
      }}
    >
      <Field label="일용직 사원" required>
        <LookupSelect table="daily_worker" role={role} value={workerId} onChange={setWorkerId} />
      </Field>
      <Field label="급여 지급일" required>
        <DateInput value={payDate} onChange={setPayDate} />
      </Field>
      <Field label="근무일수" required>
        <NumberInput value={workDays} onChange={setWorkDays} />
      </Field>
      <Field label="지급 금액" required>
        <NumberInput value={payAmount} onChange={setPayAmount} />
      </Field>
      <Field label="원천징수세액">
        <NumberInput value={tax} onChange={setTax} />
      </Field>
    </Form>
  );
}

function DetailView({ id, role, onEdit, onClose }: { id: number; role: string; onEdit: () => void; onClose: () => void }) {
  const { data, error, loading } = useData<Row>(() => call('GET', `/daily-payrolls/${id}`, role), [id]);
  if (loading) {
    return <div>불러오는 중…</div>;
  }
  if (error || !data) {
    return <ErrorText text={error || '내용을 불러오지 못했습니다.'} />;
  }
  const open = data.closingStatus !== '마감';
  return (
    <div>
      <Pairs
        items={[
          ['일용직 급여 ID', String(data.dailyPayrollId)],
          ['성명', String(data.workerName)],
          ['급여 지급일', <DateText value={data.payDate} />],
          ['근무일수', <Num value={data.workDays} />],
          ['지급 금액', <Num value={data.payAmount} />],
          ['원천징수세액', <Num value={data.withholdingTax} />],
          ['마감 상태', <Badge value={data.closingStatus} />],
        ]}
      />
      {open && (
        <div>
          <button type="button" onClick={onEdit}>수정</button>
          <button type="button" onClick={onClose}>확정</button>
        </div>
      )}
    </div>
  );
}

function EditForm({ id, role, notify, onDone }: { id: number; role: string; notify: (t: string) => void; onDone: () => void }) {
  const { data, error, loading } = useData<Row>(() => call('GET', `/daily-payrolls/${id}`, role), [id]);
  const [workDays, setWorkDays] = useState<number | string | undefined>(undefined);
  const [payAmount, setPayAmount] = useState<number | string | undefined>(undefined);
  const [tax, setTax] = useState<number | string | undefined>(undefined);
  if (loading) {
    return <div>불러오는 중…</div>;
  }
  if (error || !data) {
    return <ErrorText text={error || '내용을 불러오지 못했습니다.'} />;
  }
  const wd = workDays === undefined ? data.workDays : workDays;
  const pa = payAmount === undefined ? data.payAmount : payAmount;
  const tx = tax === undefined ? data.withholdingTax : tax;
  return (
    <Form
      submit="저장"
      onSubmit={async () => {
        if (wd === '' || pa === '') {
          throw new Error('근무일수와 지급 금액은 비울 수 없습니다.');
        }
        const body: Row = { workDays: wd, payAmount: pa };
        if (tx !== '' && tx !== null && tx !== undefined) {
          body.withholdingTax = tx;
        }
        await call('PATCH', `/daily-payrolls/${id}`, role, body);
        notify('지급 내역을 수정했습니다.');
        onDone();
      }}
    >
      <Field label="근무일수">
        <NumberInput value={wd} onChange={setWorkDays} />
      </Field>
      <Field label="지급 금액">
        <NumberInput value={pa} onChange={setPayAmount} />
      </Field>
      <Field label="원천징수세액">
        <NumberInput value={tx} onChange={setTax} />
      </Field>
    </Form>
  );
}

export default function FnSfr02305Page({ role, notify }: PageProps) {
  const [workerIdInput, setWorkerIdInput] = useState<number | string>('');
  const [payDateInput, setPayDateInput] = useState('');
  const [workerId, setWorkerId] = useState<number | string>('');
  const [payDate, setPayDate] = useState('');
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode | null>(null);
  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/daily-payrolls', role, undefined, { dailyWorkerId: workerId, payDate, page, size: 20 }),
    [workerId, payDate, page],
  );
  const rows = data ? data.items : [];
  const pending = rows.filter((r) => r.closingStatus !== '마감');
  const done = () => {
    setMode(null);
    reload();
  };
  return (
    <div className="bento">
      <section className="box span-12">
        <h2>지급 현황</h2>
        <Tiles
          items={[
            ['전체 건수', <Num value={data ? data.total : 0} />],
            ['이 쪽 확정 대기', <Num value={pending.length} />],
            ['이 쪽 확정 완료', <Num value={rows.length - pending.length} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>지급명세서</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setWorkerId(workerIdInput);
            setPayDate(payDateInput);
          }}
          onReset={() => {
            setWorkerIdInput('');
            setPayDateInput('');
            setWorkerId('');
            setPayDate('');
            setPage(0);
          }}
        >
          <Field label="일용직 사원">
            <LookupSelect table="daily_worker" role={role} value={workerIdInput} onChange={setWorkerIdInput} />
          </Field>
          <Field label="급여 지급일">
            <DateInput value={payDateInput} onChange={setPayDateInput} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={() => setMode({ kind: 'create' })}>지급 내역 등록</button>
        </Band>
        {error && <ErrorText text={error} />}
        <DataTable
          rows={rows}
          empty={loading ? '불러오는 중…' : '지급 내역이 없습니다.'}
          onRowClick={(r) => setMode({ kind: 'detail', id: Number(r.dailyPayrollId) })}
          columns={[
            { key: 'dailyWorkerId', label: '일용직 사원', render: (r) => <RefName table="daily_worker" role={role} value={r.dailyWorkerId} /> },
            { key: 'payDate', label: '급여 지급일', render: (r) => <DateText value={r.payDate} /> },
            { key: 'workDays', label: '근무일수', render: (r) => <Num value={r.workDays} /> },
            { key: 'payAmount', label: '지급 금액', render: (r) => <Num value={r.payAmount} /> },
            { key: 'withholdingTax', label: '원천징수세액', render: (r) => <Num value={r.withholdingTax} /> },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r.closingStatus} /> },
          ]}
        />
        <Pager page={data ? data.page : 0} size={data ? data.size : 20} total={data ? data.total : 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>확정 대기</h2>
        <DataTable
          rows={pending}
          empty="확정 대기 내역이 없습니다."
          onRowClick={(r) => setMode({ kind: 'detail', id: Number(r.dailyPayrollId) })}
          columns={[
            { key: 'dailyWorkerId', label: '일용직 사원', render: (r) => <RefName table="daily_worker" role={role} value={r.dailyWorkerId} /> },
            { key: 'payAmount', label: '지급 금액', render: (r) => <Num value={r.payAmount} /> },
          ]}
        />
      </section>
      {mode && mode.kind === 'create' && (
        <Drawer title="지급 내역 등록" onClose={() => setMode(null)}>
          <CreateForm role={role} notify={notify} onDone={done} />
        </Drawer>
      )}
      {mode && mode.kind === 'detail' && (
        <Drawer title="원천징수영수증" onClose={() => setMode(null)}>
          <DetailView
            id={mode.id}
            role={role}
            onEdit={() => setMode({ kind: 'edit', id: mode.id })}
            onClose={() => setMode({ kind: 'close', id: mode.id })}
          />
        </Drawer>
      )}
      {mode && mode.kind === 'edit' && (
        <Drawer title="지급 내역 수정" onClose={() => setMode(null)}>
          <EditForm id={mode.id} role={role} notify={notify} onDone={done} />
        </Drawer>
      )}
      {mode && mode.kind === 'close' && (
        <Drawer title="지급명세서 확정" onClose={() => setMode(null)}>
          <Form
            submit="확정"
            danger
            note="확정하면 확정 취소 절차 없이는 수정할 수 없습니다."
            onSubmit={async () => {
              await call('POST', `/daily-payrolls/${mode.id}/close`, role, {});
              notify('지급명세서를 확정했습니다.');
              done();
            }}
          />
        </Drawer>
      )}
    </div>
  );
}
